// Side-effect-free randomized /test targets. Real AI requests are never generated by /test.
export const aiPerformanceTests={
 'ai-perf-token-budget':{description:'2^n token setting boundaries',generate:()=>[8+Math.floor(Math.random()*8)],run:([n])=>2**n,verify:([n],x)=>x>=256&&x<=32768&&x===2**n},
 'ai-perf-memory':{description:'QA pairs -> maximum message count',generate:()=>[Math.floor(Math.random()*26)],run:([n])=>Math.min(30,n*2+1),verify:([n],x)=>x===Math.min(30,n*2+1)},
 'ai-perf-status':{description:'stream terminal status classification',generate:()=>[['completed','failed','incomplete','cancelled'][Math.floor(Math.random()*4)]],run:([s])=>s==='completed'?'success':'not_completed',verify:([s],v)=>v===(s==='completed'?'success':'not_completed')}
};
